import cProfile
import io
import pstats


def parse_row(line):
    return [f.strip() for f in line.split(",")]


def clean(rows):
    return [r for r in rows if r[2] != "0"]


def score(rows):
    return sum(int(r[2]) for r in rows)


def main():
    lines = [f"name{i},city{i},{i % 7}" for i in range(2000)]
    rows = [parse_row(l) for l in lines]
    rows = clean(rows)
    return score(rows)


