class SearchIndex:
    def __init__(self, docs):
        self.docs = docs
        self.index = None
        self.build_units = 0

    def search(self, term):
        if self.index is None:
            self.index = {}
            for d in self.docs:
                self.build_units += 1
                for w in d.split():
                    self.index.setdefault(w, 0)
                    self.index[w] += 1
        return self.index.get(term, 0)


docs = [f"doc {i} about topic{i % 5}" for i in range(1000)]
idx = SearchIndex(docs)
for call in range(1, 6):
    before = idx.build_units
    idx.search("about")
    print(f"call {call}: index-build work units = {idx.build_units - before}")

import time


def bench(fn, repeats=5):
    best = None
    for _ in range(repeats):
        t0 = time.perf_counter()
        fn()
        dt = time.perf_counter() - t0
        best = dt if best is None else min(best, dt)
    return best


