def pairwise_work(n):
    count = 0
    data = list(range(n))
    for i in range(n):
        for j in range(i + 1, n):
            count += 1
            _ = data[i] == data[j]
    return count


for n in (200, 400):
    print(f"n={n}: {pairwise_work(n)} comparisons")

import random


class Key:
    comparisons = 0

    def __init__(self, v):
        self.v = v

    def __lt__(self, other):
        Key.comparisons += 1
        return self.v < other.v

    def __eq__(self, other):
        return isinstance(other, Key) and self.v == other.v

    def __hash__(self):
        return hash(self.v)


def resorting(values):
    Key.comparisons = 0
    out = []
    for v in values:
        out.append(Key(v))
        out.sort()
    return Key.comparisons


def sort_once(values):
    Key.comparisons = 0
    out = [Key(v) for v in values]
    out.sort()
    return Key.comparisons


