print("sort once at the end:      ", sort_once(values), "comparisons")

calls = 0


def normalize(text):
    global calls
    calls += 1
    return text.strip().lower()


def count_matches_slow(rows, target):
    hits = 0
    for row in rows:
        if normalize(row) == normalize(target):
            hits += 1
    return hits


def count_matches_fast(rows, target):
    wanted = normalize(target)
    hits = 0
    for row in rows:
        if normalize(row) == wanted:
            hits += 1
    return hits


