def unique_slow(values):
    seen_list = []
    comparisons = 0
    for v in values:
        hit = False
        for s in seen_list:
            comparisons += 1
            if s == v:
                hit = True
                break
        if not hit:
            seen_list.append(v)
    return seen_list, comparisons


values = [i % 100 for i in range(5000)]  # 100 distinct values, each repeated 50 times
