calls2 = 0


@lru_cache(maxsize=None)
def fib2(n):
    global calls2
    calls2 += 1
    return n if n < 2 else fib2(n - 1) + fib2(n - 2)


print("fib(20) memoized =", fib2(20), "took", calls2, "actual computations")

class Cache:
    def __init__(self):
        self.store = {}
        self.hits = 0
        self.misses = 0

    def get_or_compute(self, key, compute):
        if key in self.store:
            self.hits += 1
            return self.store[key]
        self.misses += 1
        value = compute(key)
        self.store[key] = value
        return value


cache = Cache()
# every request carries a unique session token, so the key never repeats
