def overall_speedup(fraction, speedup):
    return 1 / ((1 - fraction) + fraction / speedup)


profile = {"parsing": 0.62, "scoring": 0.30, "formatting": 0.06, "logging": 0.02}
for name, frac in profile.items():
    cap = overall_speedup(frac, float("inf"))
    print(f"making {name} infinitely fast caps the total speedup at {cap:.2f}x")
