def run_report(rows, catalog, fast):
    ops = {"price_lookups": 0, "format_steps": 0}
    if fast:
        price_of = {c["sku"]: c["price"] for c in catalog}
    total = 0
    for r in rows:
        if fast:
            ops["price_lookups"] += 1
            p = price_of[r["sku"]]
        else:
            for c in catalog:
                ops["price_lookups"] += 1
                if c["sku"] == r["sku"]:
                    p = c["price"]
                    break
        ops["format_steps"] += 1
        total += p * r["qty"]
    return total, ops


