rows = [{"sku": f"S{i % 200}", "qty": 2} for i in range(1000)]

t1, ops1 = run_report(rows, catalog, False)
t2, ops2 = run_report(rows, catalog, True)
print("before:", t1, ops1)
print("after: ", t2, ops2)
print("identical totals:", t1 == t2)

