def import_contacts(rows, use_index):
    ops = 0
    out = []
    if use_index:
        seen = set()
        for r in rows:
            ops += 1
            if r not in seen:
                seen.add(r)
                out.append(r)
    else:
        for r in rows:
            for s in out:
                ops += 1
                if s == r:
                    break
            else:
                out.append(r)
    return out, ops


